# Compute count of column 'Number' grouped by 'Type'
print(f"🔧 Computing count of 'Number' grouped by 'Type'")

# Check if columns exist and operation is valid
if 'Number' not in df.columns:
    print(f"❌ Error: Column 'Number' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Type' not in df.columns:
    print(f"❌ Error: Group by column 'Type' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Type')['Number'].count()
        elif "count" == "sum":
            result = df.groupby('Type')['Number'].sum()
        elif "count" == "avg":
            result = df.groupby('Type')['Number'].mean()
        elif "count" == "min":
            result = df.groupby('Type')['Number'].min()
        elif "count" == "max":
            result = df.groupby('Type')['Number'].max()

        print(f"✅ Count of 'Number' by 'Type':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Type', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Number', 'Type']].dtypes}")
